1	use std::env;
2	use std::ffi::{OsStr, OsString};
3	use std::fs;
4	use std::path::Path;
5	use std::process::ExitCode;
6	
7	const VERSION: &str = "0.1.0";
8	
9	const USAGE: &str = "\
10	Usage:
11	    roottrace root <file>
12	    roottrace prove <file> <record-index>
13	    roottrace verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
14	    roottrace --version
15	
16	Commands:
17	    root <file>
18	        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
19	        as one line of 64 lowercase hexadecimal characters.
20	
21	    prove <file> <record-index>
22	        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
23	        record at <record-index> within the whole batch. The index is
24	        0-based and counts records in file order: 0 is the first record,
25	        1 the second, and so on; the same content at multiple positions gets
26	        the proof for the exact position given, with no deduplication. Output
27	        is one JSON object with the fields tree_size, leaf_index, root and
28	        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
29	        exactly one record).
30	
31	        Example:
32	            roottrace prove batch.txt 0
33	
34	    verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
35	        Verify an inclusion proof produced by `prove` without needing the
36	        whole batch. The record file holds the raw bytes of exactly one
37	        target record (no LF splitting, byte for byte including any trailing
38	        LF/space/CR, NUL and non-UTF-8 bytes; an empty file is one empty
39	        record). The proof is read as one complete JSON object. The trusted
40	        tree size (an ASCII decimal positive integer) and the trusted root
41	        (64 lowercase hexadecimal characters) must be confirmed
42	        independently; they are never taken from fields inside the proof.
43	        On success stdout is exactly \"verified\\n\", stderr is empty and the
44	        exit status is 0.
45	
46	        Example:
47	            roottrace verify record.bin proof.json 9 a8a3e76e...723adc3
48	
49	Exit status:
50	    0  success
51	    1  an input file cannot be read, the proof is malformed, or verification fails
52	    2  usage error (unknown command, missing or extra arguments, bad arguments)";
53	
54	fn main() -> ExitCode {
55	    // Raw OS arguments: file paths are handed to the filesystem exactly as
56	    // received, byte for byte. On Unix a path may contain bytes that are not
57	    // valid UTF-8 (e.g. 0xff); such a path is not invalid and must reach the
58	    // file rather than aborting argument collection. The command name, the
59	    // record index and the trusted tree size/root arguments are required to
60	    // be UTF-8 text.
61	    let args: Vec<OsString> = env::args_os().skip(1).collect();
62	    match args.as_slice() {
63	        [flag] if flag == OsStr::new("--version") => {
64	            println!("roottrace {VERSION}");
65	            ExitCode::SUCCESS
66	        }
67	        [cmd, path] if cmd == OsStr::new("root") => match merkle_root_of_file(Path::new(path)) {
68	            Ok(root) => {
69	                println!("{}", hex(&root));
70	                ExitCode::SUCCESS
71	            }
72	            Err(reason) => {
73	                eprintln!("roottrace: {reason}");
74	                ExitCode::FAILURE
75	            }
76	        },
77	        [cmd, path, index] if cmd == OsStr::new("prove") => match parse_index(index) {
78	            Some(index) => match proof_for_file(Path::new(path), index) {
79	                Ok(proof) => {
80	                    println!("{}", proof);
81	                    ExitCode::SUCCESS
82	                }
83	                Err(ProveError::Read(reason)) => {
84	                    eprintln!("roottrace: {reason}");
85	                    ExitCode::FAILURE
86	                }
87	                Err(ProveError::Missing(index, size)) => {
88	                    if size == 0 {
89	                        eprintln!(
90	                            "roottrace: record index {index} does not exist: the file holds zero records"
91	                        );
92	                    } else {
93	                        eprintln!(
94	                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
95	                            size - 1
96	                        );
97	                    }
98	                    ExitCode::FAILURE
99	                }
100	            },
101	            None => {
102	                let shown = index.to_string_lossy();
103	                eprintln!("roottrace: invalid record index '{shown}': expected a decimal non-negative integer of ASCII digits");
104	                eprintln!("{USAGE}");
105	                ExitCode::from(2)
106	            }
107	        },
108	        [cmd, path, proof_path, size_arg, root_arg] if cmd == OsStr::new("verify") => {
109	            match (parse_trusted_size(size_arg), parse_trusted_root(root_arg)) {
110	                (Some(trusted_size), Some(trusted_root)) => {
111	                    match verify_files(Path::new(path), Path::new(proof_path), trusted_size, &trusted_root) {
112	                        Ok(()) => {
113	                            println!("verified");
114	                            ExitCode::SUCCESS
115	                        }
116	                        Err(VerifyError::Read { path, source }) => {
117	                            eprintln!(
118	                                "roottrace: cannot read '{}': {source}",
119	                                display_path(&path)
120	                            );
121	                            ExitCode::FAILURE
122	                        }
123	                        Err(VerifyError::MalformedProof(reason)) => {
124	                            eprintln!("roottrace: invalid proof: {reason}");
125	                            ExitCode::FAILURE
126	                        }
127	                        Err(VerifyError::Failed(reason)) => {
128	                            eprintln!("roottrace: verification failed: {reason}");
129	                            ExitCode::FAILURE
130	                        }
131	                    }
132	                }
133	                (bad_size, bad_root) => {
134	                    if bad_size.is_none() {
135	                        let shown = size_arg.to_string_lossy();
136	                        eprintln!(
137	                            "roottrace: invalid trusted tree size '{shown}': expected an ASCII decimal positive integer within unsigned 64-bit range"
138	                        );
139	                    }
140	                    if bad_root.is_none() {
141	                        let shown = root_arg.to_string_lossy();
142	                        eprintln!(
143	                            "roottrace: invalid trusted root '{shown}': expected exactly 64 lowercase hexadecimal characters"
144	                        );
145	                    }
146	                    eprintln!("{USAGE}");
147	                    ExitCode::from(2)
148	                }
149	            }
150	        }
151	        _ => {
152	            eprintln!("{USAGE}");
153	            ExitCode::from(2)
154	        }
155	    }
156	}
157	
158	enum ProveError {
159	    Read(String),
160	    Missing(u64, u64),
161	}
162	
163	/// Failures reported by `verify`, kept separate so that malformed proofs and
164	/// cryptographic mismatches both exit 1 but say different things on stderr.
165	enum VerifyError {
166	    /// One of the two input paths cannot be read (missing, a directory, ...).
167	    Read { path: std::path::PathBuf, source: std::io::Error },
168	    /// The proof bytes are not a well-formed proof object.
169	    MalformedProof(String),
170	    /// The proof is well-formed but does not establish the claimed inclusion
171	    /// against the independently trusted tree size and root.
172	    Failed(String),
173	}
174	
175	/// Read the two input files and run an RFC 6962 inclusion check. The record
176	/// file's ENTIRE byte content is the target record: no LF splitting and no
177	/// trimming of trailing LF, space or CR; NUL and non-UTF-8 bytes take part as
178	/// they are. A zero-byte file is one empty record.
179	fn verify_files(
180	    record_path: &Path,
181	    proof_path: &Path,
182	    trusted_size: u64,
183	    trusted_root: &[u8; 32],
184	) -> Result<(), VerifyError> {
185	    let record = fs::read(record_path).map_err(|source| VerifyError::Read {
186	        path: record_path.to_path_buf(),
187	        source,
188	    })?;
189	    let proof_bytes = fs::read(proof_path).map_err(|source| VerifyError::Read {
190	        path: proof_path.to_path_buf(),
191	        source,
192	    })?;
193	    let proof = parse_proof(&proof_bytes).map_err(VerifyError::MalformedProof)?;
194	    verify_proof(&proof, &record, trusted_size, trusted_root).map_err(VerifyError::Failed)
195	}
196	
197	/// Parse the trusted tree size given on the command line: one or more ASCII
198	/// decimal digits naming a POSITIVE 64-bit unsigned integer. Unlike a record
199	/// index, zero is not accepted (it cannot be a tree that contains a record).
200	/// Anything else (sign, whitespace, non-UTF-8 bytes, a value above u64::MAX)
201	/// is a usage error.
202	fn parse_trusted_size(arg: &OsStr) -> Option<u64> {
203	    let text = arg.to_str()?;
204	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
205	        return None;
206	    }
207	    let mut value: u64 = 0;
208	    for b in text.bytes() {
209	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
210	    }
211	    if value == 0 {
212	        return None;
213	    }
214	    Some(value)
215	}
216	
217	/// Parse the trusted root given on the command line: exactly 64 lowercase
218	/// ASCII hexadecimal characters (32 bytes). Uppercase, wrong length, non-hex
219	/// or non-UTF-8 bytes are usage errors.
220	fn parse_trusted_root(arg: &OsStr) -> Option<[u8; 32]> {
221	    let text = arg.to_str()?;
222	    if text.len() != 64 || !text.bytes().all(is_lower_hex) {
223	        return None;
224	    }
225	    let bytes = text.as_bytes();
226	    let mut out = [0u8; 32];
227	    for (i, pair) in bytes.chunks_exact(2).enumerate() {
228	        out[i] = (hex_nibble(pair[0])? << 4) | hex_nibble(pair[1])?;
229	    }
230	    Some(out)
231	}
232	
233	fn is_lower_hex(b: u8) -> bool {
234	    b.is_ascii_digit() || (b'a'..=b'f').contains(&b)
235	}
236	
237	fn hex_nibble(b: u8) -> Option<u8> {
238	    match b {
239	        b'0'..=b'9' => Some(b - b'0'),
240	        b'a'..=b'f' => Some(b - b'a' + 10),
241	        _ => None,
242	    }
243	}
244	
245	// --- Proof parsing -----------------------------------------------------------
246	//
247	// The proof must be ONE complete JSON object. `prove` output is plain JSON,
248	// but the file may also arrive over a channel that reorders fields or changes
249	// whitespace, so both are accepted. Nothing else is: a truncated value, a
250	// duplicate key, a value of the wrong JSON type, a number that is not an
251	// exact unsigned 64-bit integer, a non-lowercase/non-64-char hash, trailing
252	// bytes after the object, or an empty file all make the proof invalid.
253	// Parsing is structural: no text decoding of the proof is required for the
254	// hashes, and integer fields are accumulated digit by digit so a value above
255	// u64::MAX (including 1e400) is rejected rather than wrapped or approximated.
256	
257	/// The fields of a well-formed inclusion proof.
258	struct Proof {
259	    tree_size: u64,
260	    leaf_index: u64,
261	    root: [u8; 32],
262	    audit_path: Vec<[u8; 32]>,
263	}
264	
265	struct ProofParser<'a> {
266	    bytes: &'a [u8],
267	    pos: usize,
268	}
269	
270	fn parse_proof(input: &[u8]) -> Result<Proof, String> {
271	    let mut p = ProofParser { bytes: input, pos: 0 };
272	    p.ws();
273	    let proof = p.parse_object().map_err(|e| e.to_string())?;
274	    p.ws();
275	    if p.pos != p.bytes.len() {
276	        return Err("trailing data after the JSON object".to_string());
277	    }
278	    let tree_size = proof.tree_size.ok_or_else(|| "missing field 'tree_size'".to_string())?;
279	    let leaf_index = proof.leaf_index.ok_or_else(|| "missing field 'leaf_index'".to_string())?;
280	    let root = proof.root.ok_or_else(|| "missing field 'root'".to_string())?;
281	    let audit_path =
282	        proof.audit_path.ok_or_else(|| "missing field 'audit_path'".to_string())?;
283	    if tree_size == 0 {
284	        return Err("tree_size must be positive".to_string());
285	    }
286	    if leaf_index >= tree_size {
287	        return Err(format!(
288	            "leaf_index {leaf_index} is out of range for tree_size {tree_size}"
289	        ));
290	    }
291	    Ok(Proof { tree_size, leaf_index, root, audit_path })
292	}
293	
294	/// Accumulator for the four recognised object members; a `Some` already
295	/// present when the same key is seen again makes the proof invalid.
296	struct ProofFields {
297	    tree_size: Option<u64>,
298	    leaf_index: Option<u64>,
299	    root: Option<[u8; 32]>,
300	    audit_path: Option<Vec<[u8; 32]>>,
301	}
302	
303	impl<'a> ProofParser<'a> {
304	    fn ws(&mut self) {
305	        while self.pos < self.bytes.len() && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r') {
306	            self.pos += 1;
307	        }
308	    }
309	
310	    fn peek(&self) -> Option<u8> {
311	        self.bytes.get(self.pos).copied()
312	    }
313	
314	    fn eat(&mut self, b: u8) -> Result<(), String> {
315	        if self.peek() == Some(b) {
316	            self.pos += 1;
317	            Ok(())
318	        } else {
319	            Err(format!("expected '{}' at byte {}", b as char, self.pos))
320	        }
321	    }
322	
323	    fn parse_object(&mut self) -> Result<ProofFields, String> {
324	        self.eat(b'{')?;
325	        let mut fields = ProofFields {
326	            tree_size: None,
327	            leaf_index: None,
328	            root: None,
329	            audit_path: None,
330	        };
331	        self.ws();
332	        if self.peek() == Some(b'}') {
333	            self.pos += 1;
334	            return Err("empty object: none of the required fields are present".to_string());
335	        }
336	        loop {
337	            self.ws();
338	            let key = self.parse_string()?;
339	            self.ws();
340	            self.eat(b':')?;
341	            self.ws();
342	            match key.as_str() {
343	                "tree_size" => {
344	                    if fields.tree_size.is_some() {
345	                        return Err("duplicate field 'tree_size'".to_string());
346	                    }
347	                    fields.tree_size = Some(self.parse_u64()?);
348	                }
349	                "leaf_index" => {
350	                    if fields.leaf_index.is_some() {
351	                        return Err("duplicate field 'leaf_index'".to_string());
352	                    }
353	                    fields.leaf_index = Some(self.parse_u64()?);
354	                }
355	                "root" => {
356	                    if fields.root.is_some() {
357	                        return Err("duplicate field 'root'".to_string());
358	                    }
359	                    fields.root = Some(self.parse_hash()?);
360	                }
361	                "audit_path" => {
362	                    if fields.audit_path.is_some() {
363	                        return Err("duplicate field 'audit_path'".to_string());
364	                    }
365	                    fields.audit_path = Some(self.parse_hash_array()?);
366	                }
367	                other => return Err(format!("unexpected field '{other}'")),
368	            }
369	            self.ws();
370	            match self.peek() {
371	                Some(b',') => {
372	                    self.pos += 1;
373	                }
374	                Some(b'}') => {
375	                    self.pos += 1;
376	                    break;
377	                }
378	                _ => return Err(format!("expected ',' or '}}' at byte {}", self.pos)),
379	            }
380	        }
381	        Ok(fields)
382	    }
383	
384	    /// A JSON string returned as UTF-8 text. Proof keys are ASCII; escapes
385	    /// (including `\uXXXX`) are decoded so a spelled-out key cannot bypass the
386	    /// recognized-name matching. Any string value anywhere is gated through
387	    /// here, so invalid escapes or an unclosed string reject the proof.
388	    fn parse_string(&mut self) -> Result<String, String> {
389	        self.eat(b'"')?;
390	        let mut out = String::new();
391	        loop {
392	            match self.peek() {
393	                None => return Err("unterminated string".to_string()),
394	                Some(b'"') => {
395	                    self.pos += 1;
396	                    break;
397	                }
398	                Some(b'\\') => {
399	                    self.pos += 1;
400	                    match self.peek() {
401	                        Some(b'"') => out.push('"'),
402	                        Some(b'\\') => out.push('\\'),
403	                        Some(b'/') => out.push('/'),
404	                        Some(b'b') => out.push('\u{0008}'),
405	                        Some(b'f') => out.push('\u{000C}'),
406	                        Some(b'n') => out.push('\n'),
407	                        Some(b'r') => out.push('\r'),
408	                        Some(b't') => out.push('\t'),
409	                        Some(b'u') => {
410	                            self.pos += 1;
411	                            let cp = self.parse_hex4()?;
412	                            // High surrogate demands a matching low surrogate.
413	                            let cp = if (0xD800..=0xDBFF).contains(&cp) {
414	                                if self.peek() != Some(b'\\') {
415	                                    return Err("lone high surrogate".to_string());
416	                                }
417	                                self.pos += 1;
418	                                if self.peek() != Some(b'u') {
419	                                    return Err("lone high surrogate".to_string());
420	                                }
421	                                self.pos += 1;
422	                                let lo = self.parse_hex4()?;
423	                                if !(0xDC00..=0xDFFF).contains(&lo) {
424	                                    return Err("high surrogate not followed by a low surrogate".to_string());
425	                                }
426	                                0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
427	                            } else if (0xDC00..=0xDFFF).contains(&cp) {
428	                                return Err("lone low surrogate".to_string());
429	                            } else {
430	                                cp
431	                            };
432	                            match char::from_u32(cp) {
433	                                Some(c) => out.push(c),
434	                                None => return Err("invalid unicode escape".to_string()),
435	                            }
436	                            continue;
437	                        }
438	                        _ => return Err("invalid escape sequence".to_string()),
439	                    }
440	                    self.pos += 1;
441	                }
442	                Some(_) => {
443	                    // Copy a run of ordinary bytes, reinterpreting the slice as
444	                    // UTF-8 for appending; control characters and invalid UTF-8
445	                    // inside a string are rejected. The run stops at ASCII
446	                    // delimiters only, so a multibyte sequence is never split.
447	                    let start = self.pos;
448	                    while self.pos < self.bytes.len() {
449	                        let b = self.bytes[self.pos];
450	                        if b == b'"' || b == b'\\' {
451	                            break;
452	                        }
453	                        if b < 0x20 {
454	                            return Err("unescaped control character in string".to_string());
455	                        }
456	                        self.pos += 1;
457	                    }
458	                    match std::str::from_utf8(&self.bytes[start..self.pos]) {
459	                        Ok(s) => out.push_str(s),
460	                        Err(_) => return Err("string is not valid UTF-8".to_string()),
461	                    }
462	                }
463	            }
464	        }
465	        Ok(out)
466	    }
467	
468	    fn parse_hex4(&mut self) -> Result<u32, String> {
469	        if self.pos + 4 > self.bytes.len() {
470	            return Err("truncated unicode escape".to_string());
471	        }
472	        let mut v = 0u32;
473	        for _ in 0..4 {
474	            let b = self.bytes[self.pos];
475	            self.pos += 1;
476	            let n = match b {
477	                b'0'..=b'9' => u32::from(b - b'0'),
478	                b'a'..=b'f' => u32::from(b - b'a' + 10),
479	                b'A'..=b'F' => u32::from(b - b'A' + 10),
480	                _ => return Err("invalid hex digit in unicode escape".to_string()),
481	            };
482	            v = (v << 4) | n;
483	        }
484	        Ok(v)
485	    }
486	
487	    /// A JSON number accepted only when it is an exact unsigned 64-bit
488	    /// integer token: digits only, no sign, fraction or exponent.
489	    fn parse_u64(&mut self) -> Result<u64, String> {
490	        let start = self.pos;
491	        while self.peek().is_some_and(|b| b.is_ascii_digit()) {
492	            self.pos += 1;
493	        }
494	        if start == self.pos {
495	            return Err("expected an unsigned integer".to_string());
496	        }
497	        // Canonical JSON integer token: "0" alone is allowed, but no leading
498	        // zeros (so "01" is rejected, not read as 1).
499	        if self.pos - start > 1 && self.bytes[start] == b'0' {
500	            return Err("integer must not have leading zeros".to_string());
501	        }
502	        if self.peek().is_some_and(|b| matches!(b, b'.' | b'e' | b'E' | b'+' | b'-')) {
503	            return Err("number must be an unsigned 64-bit integer".to_string());
504	        }
505	        let text = std::str::from_utf8(&self.bytes[start..self.pos])
506	            .map_err(|_| "integer is not ASCII".to_string())?;
507	        let mut value: u64 = 0;
508	        for b in text.bytes() {
509	            value = value
510	                .checked_mul(10)
511	                .and_then(|v| v.checked_add(u64::from(b - b'0')))
512	                .ok_or_else(|| "integer exceeds unsigned 64-bit range".to_string())?;
513	        }
514	        Ok(value)
515	    }
516	
517	    /// A JSON string that must contain exactly 64 lowercase hexadecimal
518	    /// characters, decoded to 32 bytes.
519	    fn parse_hash(&mut self) -> Result<[u8; 32], String> {
520	        let s = self.parse_string()?;
521	        if s.len() != 64 || !s.bytes().all(is_lower_hex) {
522	            return Err("hash must be a string of 64 lowercase hexadecimal characters".to_string());
523	        }
524	        let bytes = s.as_bytes();
525	        let mut out = [0u8; 32];
526	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
527	            out[i] = (hex_nibble(pair[0]).unwrap() << 4) | hex_nibble(pair[1]).unwrap();
528	        }
529	        Ok(out)
530	    }
531	
532	    fn parse_hash_array(&mut self) -> Result<Vec<[u8; 32]>, String> {
533	        self.eat(b'[')?;
534	        let mut hashes = Vec::new();
535	        self.ws();
536	        if self.peek() == Some(b']') {
537	            self.pos += 1;
538	            return Ok(hashes);
539	        }
540	        loop {
541	            self.ws();
542	            hashes.push(self.parse_hash()?);
543	            self.ws();
544	            match self.peek() {
545	                Some(b',') => {
546	                    self.pos += 1;
547	                }
548	                Some(b']') => {
549	                    self.pos += 1;
550	                    break;
551	                }
552	                _ => return Err(format!("expected ',' or ']' at byte {}", self.pos)),
553	            }
554	        }
555	        Ok(hashes)
556	    }
557	}
558	
559	/// Check a well-formed proof against the independently trusted tree size and
560	/// root, exactly per RFC 6962 section 2.1.1:
561	///
562	/// 1. the proof's `tree_size` must equal the trusted size (the proof must not
563	///    name its own trust anchor);
564	/// 2. the proof's `root` must equal the trusted root;
565	/// 3. `leaf_index` must exist in a tree of that size (already enforced while
566	///    parsing);
567	/// 4. starting from SHA-256(0x00 || record), the audit path hashes must
568	///    recombine in the order dictated by the (possibly uneven) tree geometry
569	///    into that root, consuming every supplied hash exactly once.
570	///
571	/// Duplicate content is never searched for: the check is against the exact
572	/// `leaf_index` the proof claims. A single-record tree needs an empty path;
573	/// a path that is too short or too long for the geometry cannot succeed.
574	fn verify_proof(proof: &Proof, record: &[u8], trusted_size: u64, trusted_root: &[u8; 32]) -> Result<(), String> {
575	    if proof.tree_size != trusted_size {
576	        return Err(format!(
577	            "proof tree_size {} does not match the trusted tree size {trusted_size}",
578	            proof.tree_size
579	        ));
580	    }
581	    if proof.root != *trusted_root {
582	        return Err("proof root does not match the trusted root".to_string());
583	    }
584	    let computed = include_record(
585	        leaf_hash(record),
586	        proof.leaf_index,
587	        proof.tree_size,
588	        &proof.audit_path,
589	    )
590	    .map_err(|e| e.to_string())?;
591	    if computed != *trusted_root {
592	        return Err("record bytes or audit_path do not match the root at the claimed position".to_string());
593	    }
594	    Ok(())
595	}
