597	/// RFC 6962-bis recursive inclusion recomputation: the combination order is
598	/// derived from the subtree sizes, and the path is consumed in its given
599	/// leaf-to-root order. A missing sibling or an unconsumed leftover hash is an
600	/// error, so an over- or under-long path never verifies. Arithmetic stays in
601	/// u64 so sizes above `usize::MAX` cannot truncate on a 32-bit platform; the
602	/// recursion depth is bounded by the hashes actually present in the path.
603	fn include_record(
604	    leaf: [u8; 32],
605	    m: u64,
606	    n: u64,
607	    path: &[[u8; 32]],
608	) -> Result<[u8; 32], String> {
609	    fn sub(
610	        leaf: [u8; 32],
611	        m: u64,
612	        n: u64,
613	        path: &[[u8; 32]],
614	        pos: &mut usize,
615	    ) -> Result<[u8; 32], String> {
616	        if n == 1 {
617	            return Ok(leaf);
618	        }
619	        // Largest power of two strictly smaller than n.
620	        let k = 1u64 << (u64::BITS - 1 - (n - 1).leading_zeros());
621	        if m < k {
622	            let left = sub(leaf, m, k, path, pos)?;
623	            let right = take(path, pos)?;
624	            Ok(node_hash(&left, &right))
625	        } else {
626	            let right = sub(leaf, m - k, n - k, path, pos)?;
627	            let left = take(path, pos)?;
628	            Ok(node_hash(&left, &right))
629	        }
630	    }
631	    fn take(path: &[[u8; 32]], pos: &mut usize) -> Result<[u8; 32], String> {
632	        let h = *path
633	            .get(*pos)
634	            .ok_or_else(|| "audit_path is shorter than the tree requires".to_string())?;
635	        *pos += 1;
636	        Ok(h)
637	    }
638	    let mut pos = 0;
639	    let root = sub(leaf, m, n, path, &mut pos)?;
640	    if pos != path.len() {
641	        return Err("audit_path is longer than the tree requires".to_string());
642	    }
643	    Ok(root)
644	}
