756	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
757	/// with the Merkle Audit Path for the record at `m`, computed in a single
758	/// traversal. Every leaf hash and every subtree hash is computed exactly
759	/// once: each interior hash on the path from the leaf to the root feeds both
760	/// the root computation and (for the sibling subtree) the audit path, so
761	/// producing a proof never rehashes a record byte or a subtree that already
762	/// contributed to the root.
763	///
764	/// ```text
765	/// PATH(m, [d0]) = []
766	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
767	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
768	/// ```
769	///
770	/// with k the largest power of two strictly smaller than n. Uneven batches
771	/// are handled by the recursion itself: no leaf is duplicated and no empty
772	/// record is appended to round the size up to a power of two. The returned
773	/// path is ordered from the leaf level up to the root.
774	fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
775	    let n = leaves.len();
776	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
777	    let mut path = Vec::new();
778	    let root = root_and_path_rec(leaves, m, &mut path);
779	    (root, path)
780	}
781	
782	fn root_and_path_rec(leaves: &[&[u8]], m: usize, path: &mut Vec<[u8; 32]>) -> [u8; 32] {
783	    let n = leaves.len();
784	    if n == 1 {
785	        return leaf_hash(leaves[0]);
786	    }
787	    // Largest power of two strictly smaller than n.
788	    let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
789	    if m < k {
790	        let left = root_and_path_rec(&leaves[..k], m, path);
791	        let right = mth(&leaves[k..]);
792	        path.push(right);
793	        node_hash(&left, &right)
794	    } else {
795	        let left = mth(&leaves[..k]);
796	        let right = root_and_path_rec(&leaves[k..], m - k, path);
797	        path.push(left);
798	        node_hash(&left, &right)
799	    }
800	}
