832	fn sha256(data: &[u8]) -> [u8; 32] {
833	    #[cfg(test)]
834	    SHA256_CALLS.with(|c| c.set(c.get() + 1));
835	    let mut h: [u32; 8] = [
836	        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
837	        0x5be0cd19,
838	    ];
839	
840	    let bit_len = (data.len() as u64).wrapping_mul(8);
841	    let mut msg = data.to_vec();
842	    msg.push(0x80);
843	    while msg.len() % 64 != 56 {
844	        msg.push(0);
845	    }
846	    msg.extend_from_slice(&bit_len.to_be_bytes());
847	
848	    for block in msg.chunks_exact(64) {
849	        let mut w = [0u32; 64];
850	        for (i, word) in block.chunks_exact(4).enumerate() {
851	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
852	        }
853	        for i in 16..64 {
854	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
855	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
856	            w[i] = w[i - 16]
857	                .wrapping_add(s0)
858	                .wrapping_add(w[i - 7])
859	                .wrapping_add(s1);
860	        }
861	
862	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = h;
863	        for i in 0..64 {
864	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
865	            let ch = (e & f) ^ ((!e) & g);
866	            let t1 = hh
867	                .wrapping_add(s1)
868	                .wrapping_add(ch)
869	                .wrapping_add(K[i])
870	                .wrapping_add(w[i]);
871	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
872	            let maj = (a & b) ^ (a & c) ^ (b & c);
873	            let t2 = s0.wrapping_add(maj);
874	            hh = g;
875	            g = f;
876	            f = e;
877	            e = d.wrapping_add(t1);
878	            d = c;
879	            c = b;
880	            b = a;
881	            a = t1.wrapping_add(t2);
882	        }
883	
884	        h[0] = h[0].wrapping_add(a);
885	        h[1] = h[1].wrapping_add(b);
886	        h[2] = h[2].wrapping_add(c);
887	        h[3] = h[3].wrapping_add(d);
888	        h[4] = h[4].wrapping_add(e);
889	        h[5] = h[5].wrapping_add(f);
890	        h[6] = h[6].wrapping_add(g);
891	        h[7] = h[7].wrapping_add(hh);
892	    }
893	
894	    let mut out = [0u8; 32];
895	    for (i, word) in h.iter().enumerate() {
896	        out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
897	    }
898	    out
899	}
