1038	        // cost exactly 2n - 1 SHA-256 invocations: the old two-phase
1039	        // implementation (mth for the root, then inclusion_path recomputing
1040	        // the sibling subtrees) needed strictly more for any n >= 2.
1041	        for n in [1usize, 2, 3, 4, 5, 8, 9, 10, 16, 33] {
1042	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
1043	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
1044	            for m in 0..n {
1045	                SHA256_CALLS.with(|c| c.set(0));
1046	                let _ = root_and_path(&refs, m);
1047	                let calls = SHA256_CALLS.with(|c| c.get());
1048	                assert_eq!(
1049	                    calls,
1050	                    2 * n - 1,
1051	                    "n={n}, m={m}: expected {n} leaf + {} interior hashes, each computed once",
1052	                    n - 1
1053	                );
1054	            }
1055	        }
1056	    }
