1208	    fn parse_proof_rejects_missing_fields_and_empty_or_wrong_container() {
1209	        let refs: Vec<&[u8]> = vec![b"a", b"b"];
1210	        let (root, path) = root_and_path(&refs, 0);
1211	        let full = valid_proof_bytes(2, 0, &root, &path);
1212	        assert!(parse_proof(&full).is_ok());
1213	
1214	        let drop_field = |bytes: &[u8], needle: &str| -> Vec<u8> {
1215	            let text = String::from_utf8(bytes.to_vec()).unwrap();
1216	            // Rebuild without the named member by string surgery on the
1217	            // canonical compact form emitted by proof_json.
1218	            let idx = text.find(needle).unwrap();
1219	            let mut end = idx + needle.len();
1220	            // Consume through the member's value terminator.
1221	            match needle {
1222	                "\"tree_size\":" | "\"leaf_index\":" => {
1223	                    while end < text.len()
1224	                        && text.as_bytes()[end] != b','
1225	                        && text.as_bytes()[end] != b'}'
1226	                    {
1227	                        end += 1;
1228	                    }
1229	                }
1230	                "\"root\":" => {
1231	                    while end < text.len() && text.as_bytes()[end] != b'"' {
1232	                        end += 1;
1233	                    }
1234	                    end += 1;
1235	                }
1236	                _ => {
1237	                    end = text.rfind(']').unwrap() + 1;
1238	                }
1239	            }
1240	            let mut s = String::new();
1241	            s.push_str(&text[..idx]);
1242	            let rest = &text[end..];
1243	            // Tidy the separator left by the removed member.
1244	            if rest.starts_with(',') {
1245	                s.push_str(&rest[1..]);
1246	            } else if text[..idx].ends_with(',') {
1247	                s.pop();
1248	                s.push_str(rest);
1249	            } else {
1250	                s.push_str(rest);
1251	            }
1252	            s.into_bytes()
1253	        };
1254	
1255	        for key in ["\"tree_size\":", "\"leaf_index\":", "\"root\":", "\"audit_path\":"] {
1256	            let cut = drop_field(&full, key);
1257	            assert!(parse_proof(&cut).is_err(), "proof missing {key} must be invalid: {cut:?}");
1258	        }
1259	
1260	        for bad in [
1261	            b"".as_slice(),
1262	            b"   ",
1263	            b"null",
1264	            b"[]",
1265	            b"\"x\"",
1266	            b"123",
1267	            b"{}",
1268	            b"[{\"tree_size\":1}]",
1269	        ] {
1270	            assert!(parse_proof(bad).is_err(), "{bad:?} must not parse as a proof");
1271	        }
1272	    }
