1387	    fn verify_accepts_real_proofs_at_every_position_of_many_sizes() {
1388	        let sizes: Vec<usize> = (1..=18).chain([31, 32, 33, 63, 64, 65, 100, 127, 128, 257]).collect();
1389	        for n in sizes {
1390	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
1391	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
1392	            let root = mth(&refs);
1393	            for m in 0..n {
1394	                verify_record(&refs, m, refs[m], n as u64).unwrap_or_else(|e| {
1395	                    panic!("n={n} m={m} must verify: {e}")
1396	                });
1397	                // The proof must not be trusted by itself: a different
1398	                // trusted size or root always fails.
1399	                assert!(verify_record(&refs, m, refs[m], n as u64 + 1).is_err());
1400	                let mut other_root = root;
1401	                other_root[0] ^= 0x01;
1402	                let (_, path) = root_and_path(&refs, m);
1403	                let bytes = proof_json(n as u64, m as u64, &root, &path).into_bytes();
1404	                let proof = parse_proof(&bytes).unwrap();
1405	                assert!(verify_proof(&proof, refs[m], n as u64, &other_root).is_err());
1406	            }
1407	        }
1408	    }
